import axios from 'axios';

export const createBooking = async (bookingData, userId, parkingSlotId) => {
  const res = await axios.post(
    `http://localhost:8080/api/bookings?userId=${userId}&parkingSlotId=${parkingSlotId}`,
    bookingData
  );
  return res.data;
};
